CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE merchants(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE merchant_policies(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), merchant_id UUID NOT NULL REFERENCES merchants(id), version INT NOT NULL, auto_send_receipt BOOLEAN NOT NULL DEFAULT false, auto_create_support_case BOOLEAN NOT NULL DEFAULT false, auto_refund_limit BIGINT NOT NULL DEFAULT 0 CHECK(auto_refund_limit>=0), require_human_for_high_value BOOLEAN NOT NULL DEFAULT true, require_human_for_fraud BOOLEAN NOT NULL DEFAULT true, communication_enabled BOOLEAN NOT NULL DEFAULT true, high_value_threshold BIGINT NOT NULL DEFAULT 50000, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(merchant_id,version));
CREATE TABLE customers(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), merchant_id UUID NOT NULL REFERENCES merchants(id), synthetic_external_id TEXT NOT NULL, average_transaction_amount BIGINT NOT NULL DEFAULT 0, transaction_count INT NOT NULL DEFAULT 0, previous_disputes INT NOT NULL DEFAULT 0, previous_refunds INT NOT NULL DEFAULT 0, support_contact_count INT NOT NULL DEFAULT 0, communication_opt_out BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(merchant_id,synthetic_external_id));
CREATE TABLE transactions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), merchant_id UUID NOT NULL REFERENCES merchants(id), customer_id UUID NOT NULL REFERENCES customers(id), order_id UUID, amount BIGINT NOT NULL CHECK(amount>=0), currency CHAR(3) NOT NULL, payment_method TEXT NOT NULL, merchant_descriptor TEXT NOT NULL, device_id_hash TEXT, country CHAR(2), status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX transactions_merchant_time ON transactions(merchant_id,created_at DESC);
CREATE TABLE orders(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), merchant_id UUID NOT NULL REFERENCES merchants(id), customer_id UUID NOT NULL REFERENCES customers(id), transaction_id UUID REFERENCES transactions(id), order_amount BIGINT NOT NULL CHECK(order_amount>=0), order_status TEXT NOT NULL, delivery_status TEXT NOT NULL, promised_delivery_at TIMESTAMPTZ, delivered_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE post_payment_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), merchant_id UUID NOT NULL REFERENCES merchants(id), transaction_id UUID NOT NULL REFERENCES transactions(id), customer_id UUID NOT NULL REFERENCES customers(id), event_type TEXT NOT NULL, metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX events_tx_time ON post_payment_events(transaction_id,created_at DESC);
CREATE TABLE disputes(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), merchant_id UUID NOT NULL REFERENCES merchants(id), transaction_id UUID NOT NULL REFERENCES transactions(id), customer_id UUID NOT NULL REFERENCES customers(id), reason TEXT, amount BIGINT NOT NULL, status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, resolved_at TIMESTAMPTZ);
CREATE TABLE risk_assessments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id UUID NOT NULL REFERENCES transactions(id), risk_score REAL NOT NULL CHECK(risk_score BETWEEN 0 AND 1), risk_level TEXT NOT NULL, intervention_opportunity BOOLEAN NOT NULL, signals JSONB NOT NULL DEFAULT '[]', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), model_version TEXT NOT NULL);
CREATE TABLE investigations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id UUID NOT NULL REFERENCES transactions(id), status TEXT NOT NULL, primary_hypothesis TEXT, confidence REAL CHECK(confidence BETWEEN 0 AND 1), supporting_evidence JSONB NOT NULL DEFAULT '[]', contradicting_evidence JSONB NOT NULL DEFAULT '[]', unknowns JSONB NOT NULL DEFAULT '[]', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ);
CREATE TABLE interventions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id UUID NOT NULL REFERENCES transactions(id), investigation_id UUID REFERENCES investigations(id), action_type TEXT NOT NULL, recommendation_reason TEXT NOT NULL, policy_version INT NOT NULL, approval_status TEXT NOT NULL, execution_status TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), executed_at TIMESTAMPTZ, expires_at TIMESTAMPTZ);
CREATE TABLE outcomes(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id UUID NOT NULL REFERENCES transactions(id), intervention_id UUID REFERENCES interventions(id), dispute_occurred BOOLEAN, dispute_date TIMESTAMPTZ, customer_response TEXT, complaint_after_intervention BOOLEAN, resolution_status TEXT, observation_window INTERVAL NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), entity_type TEXT NOT NULL, entity_id UUID NOT NULL, actor_type TEXT NOT NULL, actor_id TEXT, action TEXT NOT NULL, details JSONB NOT NULL DEFAULT '{}', policy_version INT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX audit_entity_time ON audit_logs(entity_type,entity_id,created_at);
